def proverb(*pieces, qualifier=None):
    lines = []
    for current, following in zip(pieces, pieces[1:]):
        lines.append(f"For want of a {current} the {following} was lost.")
    if pieces:
        if qualifier:
            lines.append(f"And all for the want of a {qualifier} {pieces[0]}.")
        else:
            lines.append(f"And all for the want of a {pieces[0]}.")
    return lines

